['Produto 3D Premium Instagram',['/producthero','/3dprint-real','/premium','/instagram-feed','/4:5'],'Uma peça impressa em 3D com acabamento premium para o feed.','Popular'],['Produto 3D Dark Story',['/producthero','/3dprint-real','/dark','/dramaticlight','/instagram-story','/9:16'],'Impacto vertical e atmosfera sofisticada para Stories.','Recomendado'],['Chaveiro 3D Instagram',['/keychain3d','/personalized','/3dprint-real','/producthero','/instagram-feed','/4:5'],'Divulgação de chaveiros personalizados em impressão 3D.','Popular'],['Chaveiro Corporativo',['/companykeychain','/personalized','/businessad','/producthero','/instagram-feed','/4:5'],'Brinde empresarial personalizado para gerar demanda B2B.','Recomendado'],['Shopee Capa',['/shopee-cover','/productwhite','/whitebg','/1:1'],'Capa objetiva e compatível com o marketplace.','Validado'],['Scroll Stopper',['/scrollstopper','/producthero','/premium','/dramaticlight','/instagram-story','/9:16'],'Anúncio de grande impacto para interromper a rolagem.','Em alta'],['Produto Minimalista',['/producthero','/minimalist','/softlight','/instagram-feed','/4:5'],'Produto com hierarquia limpa e alta legibilidade.','Validado'],['Infantil Colorido',['/kidsproduct','/colorful','/softlight','/instagram-feed','/4:5'],'Comunicação vibrante para produtos infantis.','Popular']
