const order=['PURPOSE','SUBJECT','PRESENTATION','MATERIAL','STYLE','LIGHTING','EFFECT','ENVIRONMENT','BACKGROUND','PROMOTION','PLATFORM','MARKETPLACE','FORMAT','AUDIENCE'];let selected=[];const byCode=c=>P.find(x=>x.code===c);const has=c=>selected.includes(c);const conflicts=(a,b)=>[['/whitebg','/blackbg'],['/transparent','/whitebg'],['/transparent','/blackbg']].some(x=>x.includes(a)&&x.includes(b));function canonical(a){return [...a].sort((x,y)=>order.indexOf(byCode(x)?.role)-order.indexOf(byCode(y)?.role)||x.localeCompare(y))}function valid(a){let roles={};for(const c of a){let p=byCode(c);if(!p)continue;if(['FORMAT','PLATFORM','MARKETPLACE','BACKGROUND'].includes(p.role)&&(roles[p.role]||0)>=1)return false;roles[p.role]=(roles[p.role]||0)+1;for(const d of a)if(c!==d&&conflicts(c,d))return false}return true}function compose(a){return 'Crie uma imagem publicitária profissional. '+canonical(a).map(c=>byCode(c)?.fragment).filter(Boolean).join(' ')}function recipeCard(r){return `<article class="card"><div class="card-head"><span class="tag">${r.badge}</span><span class="score">${r.score}% compatível</span></div><h3>${r.name}</h3><p>${r.desc}</p><div class="codes">${r.codes.slice(0,5).map(c=>`<span>${c}</span>`).join('')}</div><div class="card-actions"><button class="small primary" onclick='useRecipe(${JSON.stringify(r.codes)})'>Usar combinação</button><button class="small" onclick='copyText(${JSON.stringify(r.codes.join(' '))})'>Copiar</button></div></article>`}function presetCard(p){return `<article class="card"><span class="tag">${p.role}</span><h3>${p.code}</h3><p>${p.desc}</p><button class="small" onclick="add('${p.code}')">+ Builder</button></article>`}function render(){document.getElementById('recipeCards').innerHTML=R.slice(0,4).map(recipeCard).join('');document.getElementById('presetCards').innerHTML=P.slice(0,12).map(presetCard).join('');renderBuilder()}function renderBuilder(){const c=canonical(selected),good=valid(c);document.getElementById('chips').innerHTML=c.length?c.map(x=>`<span>${x}<button aria-label="Remover ${x}" onclick="remove('${x}')">×</button></span>`).join(''):'<span style="color:#777">Adicione um preset para começar</span>';document.getElementById('codeResult').textContent=c.length?c.join(' '):'—';document.getElementById('promptResult').textContent=c.length?compose(c):'Cada combinação válida gera um prompt claro, profissional e pronto para copiar.';document.getElementById('validity').textContent=good?'VALIDADO':'CONFLITO';document.getElementById('validity').style.color=good?'var(--mint)':'var(--danger)';let suggestions=P.filter(p=>!has(p.code)&&valid([...selected,p.code])).filter(p=>c.length?(!c.some(x=>byCode(x)?.role===p.role)||['STYLE','LIGHTING','EFFECT'].includes(p.role)):['/producthero','/3dprint-real','/premium','/instagram-feed','/4:5'].includes(p.code)).slice(0,7);document.getElementById('suggestions').innerHTML=suggestions.map(p=>`<button class="chip" onclick="add('${p.code}')">+ ${p.code}</button>`).join('')||'<small style="color:#aaa">Nenhuma sugestão compatível.</small>'}function add(c){if(has(c))return;let p=byCode(c),same=selected.find(x=>byCode(x)?.role===p.role&&['FORMAT','PLATFORM','MARKETPLACE','BACKGROUND'].includes(p.role));if(same){toast(`Substituído ${same} por ${c}`);selected=selected.filter(x=>x!==same)}if(!valid([...selected,c])){toast('Estes presets possuem instruções conflitantes.');return}selected.push(c);renderBuilder()}function remove(c){selected=selected.filter(x=>x!==c);renderBuilder()}function useRecipe(c){selected=[...c];renderBuilder();document.querySelector('.builder').scrollIntoView({behavior:'smooth'})}function clearBuild(){selected=[];renderBuilder()}function completeBuild(){if(!selected.length)return toast('Adicione ao menos um preset.');const match=R.filter(r=>selected.every(c=>r.codes.includes(c))).sort((a,b)=>b.score-a.score)[0];if(match){selected=[...match.codes];renderBuilder();toast('Combinação pré-validada encontrada: '+match.name)}else toast('Não há receita pré-calculada para essa seleção. Ajuste pelos complementos sugeridos.')}function copyText(s){navigator.clipboard?.writeText(s);toast('Copiado para a área de transferência')}function copyCodes(){selected.length&&copyText(canonical(selected).join(' '))}function copyPrompt(){selected.length&&copyText(compose(selected))}function toast(t){let e=document.getElementById('toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',2400)}function quick(q){document.getElementById('search').value=q;searchAll(q);document.getElementById('presetCards').scrollIntoView({behavior:'smooth'})}function searchAll(q){q=q.toLowerCase().trim();if(!q){render();return}let terms=q.replaceAll('/','').split(/\s+/);let rs=R.filter(r=>terms.every(t=>(r.name+' '+r.desc+' '+r.codes.join(' ')).toLowerCase().includes(t)||r.codes.join(' ').includes('/'+t)));let ps=P.filter(p=>terms.some(t=>(p.code+' '+p.name+' '+p.desc+' '+p.keys).toLowerCase().includes(t)));document.getElementById('recipeCards').innerHTML=rs.length?rs.map(recipeCard).join(''):'<div class="empty">Nenhuma combinação validada encontrada. Tente “produto 3D” ou “chaveiro personalizado”.</div>';document.getElementById('presetCards').innerHTML=ps.length?ps.map(presetCard).join(''):'<div class="empty">Nenhum preset encontrado.</div>'}function resetSearch(){document.getElementById('search').value='';render()}function openPalette(){document.getElementById('palette').classList.add('open');setTimeout(()=>document.getElementById('paletteInput').focus(),0);paletteSearch('')}function closePalette(){document.getElementById('palette').classList.remove('open')}function paletteSearch(q){let terms=q.toLowerCase();let a=[...R.filter(x=>(x.name+x.desc+x.codes).toLowerCase().includes(terms)).map(x=>({type:'Combinação',label:x.name,action:`useRecipe(${JSON.stringify(x.codes)})`})),...P.filter(x=>(x.code+x.name+x.desc+x.keys).toLowerCase().includes(terms)).map(x=>({type:x.role,label:x.code+' — '+x.name,action:`add('${x.code}')`}))].slice(0,10);document.getElementById('paletteResults').innerHTML=a.map(x=>`<div class="result-row"><div><b>${x.label}</b><br/><small>${x.type}</small></div><button class="small" onclick="${x.action};closePalette()">Adicionar</button></div>`).join('')||'<div class="empty">Sem resultados</div>'}function showCategories(){document.getElementById('categoryMenu').classList.toggle('open')}function showAll(){document.getElementById('search').value='';document.getElementById('categoryMenu').classList.remove('open');render();document.getElementById('presetCards').scrollIntoView({behavior:'smooth',block:'start'})}function showCategory(category){const groups={religiosos:['bíblia','bíblico','cristão','igreja','fé','oração','jerusalém','belém','devocional','versículo','natal','páscoa'],comercial:['comercial','venda','oferta','produto','marketplace','shopee','empresa','marca','preço'],marketing:['anúncio','marketing','instagram','tiktok','campanha','cta','conteúdo','prova social'],fotografia:['fotografia','foto','retrato','culinária','imobiliária','luz','cinematográfico','estúdio'],datas:['natal','páscoa','dia das mães','dia dos pais','data comemorativa','black friday','namorados','volta às aulas'],infantil:['infantil','criança','educativo','brinquedo','kids','escolar']};let terms=groups[category]||[];let text=p=>(p.code+' '+p.name+' '+p.desc+' '+p.keys).toLowerCase();let ps=P.filter(p=>terms.some(t=>text(p).includes(t)));document.getElementById('search').value=category;document.getElementById('recipeCards').innerHTML='<div class="empty">Códigos da categoria selecionada. Escolha um ou mais presets abaixo para adicionar ao Builder.</div>';document.getElementById('presetCards').innerHTML=ps.length?ps.map(presetCard).join(''):'<div class="empty">Nenhum código cadastrado nesta categoria.</div>';document.getElementById('categoryMenu').classList.remove('open');document.getElementById('presetCards').scrollIntoView({behavior:'smooth',block:'start'})}function showRecipes(){document.getElementById('search').value='';document.getElementById('recipeCards').innerHTML=R.map(recipeCard).join('');document.getElementById('recipeCards').scrollIntoView({behavior:'smooth',block:'start'})}document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}if(e.key==='Escape')closePalette()});render();
